// Wrapper for the Intel MAX 10 Modular ADC Core IP.
//
// The actual Modular ADC Core instance is generated by Quartus/Platform
// Designer. This wrapper connects its command/response interfaces to the
// oscilloscope's generic sample stream:
//
//   ADC IP response_valid/data -> sample_valid/sample_data
//
// For a single-channel oscilloscope, channel_select should normally be zero
// and the generated ADC IP should be configured for the DE10-Lite board with
// that channel in its conversion sequence.
//
// The MAX 10 ADC response interface does not provide backpressure, so the
// downstream capture logic must accept every response sample. The capture
// engine should therefore run in the same peripheral clock domain as this
// wrapper, or samples should first enter a sufficiently deep FIFO.

module max10_adc_interface #(
    parameter int ADC_WIDTH = 12,
    parameter int CHANNEL_WIDTH = 5
) (
    input  logic                         clk,
    input  logic                         rst,
    input  logic                         enable,
    input  logic [CHANNEL_WIDTH-1:0]     channel_select,
    input  logic                         adc_pll_locked,

    // Connect these signals to the generated Modular ADC Core IP.
    output logic                         adc_command_valid,
    output logic [CHANNEL_WIDTH-1:0]     adc_command_channel,
    output logic                         adc_command_startofpacket,
    output logic                         adc_command_endofpacket,
    input  logic                         adc_command_ready,

    input  logic                         adc_response_valid,
    input  logic [CHANNEL_WIDTH-1:0]     adc_response_channel,
    input  logic [ADC_WIDTH-1:0]         adc_response_data,
    input  logic                         adc_response_startofpacket,
    input  logic                         adc_response_endofpacket,
	 
	 input logic [31:0] sample_rate_hz,

    // Generic sample stream consumed by the capture engine.
    output logic                         sample_valid,
    output logic [ADC_WIDTH-1:0]         sample_data,
    output logic [CHANNEL_WIDTH-1:0]     sample_channel
);
	
	logic [31:0] sample_period;

	 
	 always_comb begin
		 case (sample_rate_hz)
			  32'd1000000: sample_period = 50;
			  32'd500000:  sample_period = 100;
			  32'd250000:  sample_period = 200;
			  32'd100000:  sample_period = 500;
			  32'd50000:   sample_period = 1000;
			  32'd20000:   sample_period = 2500;
			  32'd10000:   sample_period = 5000;
			  default:     sample_period = 50;
		 endcase
	end
	
	
	// Free-running pacing: one "sample due" every sample_period clocks (50 MHz),
	// independent of how long the ADC takes to accept each request.
	logic [31:0] pace_counter;
	logic        request_pending;

	always_ff @(posedge clk) begin
		 if (rst || !enable || !adc_pll_locked) begin
			  pace_counter    <= 32'd0;
			  request_pending <= 1'b0;
		 end else begin
			  // A request the ADC just accepted is no longer pending...
			  if (adc_command_valid && adc_command_ready)
					request_pending <= 1'b0;
			  // ...and the timer marks the next one due (this wins if both happen).
			  if (pace_counter == 0) begin
					pace_counter    <= sample_period - 1'b1;
					request_pending <= 1'b1;
			  end else begin
					pace_counter <= pace_counter - 1'b1;
			  end
		 end
	end

	always_comb begin
		 adc_command_valid         = enable && adc_pll_locked && !rst && request_pending;
		 adc_command_channel       = channel_select;
		 adc_command_startofpacket = 1'b0;
		 adc_command_endofpacket   = 1'b0;
	end

    // The response stream has no ready signal. Filter the response by channel
    // so this block remains correct if the IP is later configured for a
    // multi-channel sequence.
    always_ff @(posedge clk) begin
        if (rst) begin
            sample_valid  <= 1'b0;
            sample_data   <= '0;
            sample_channel <= '0;
        end else begin
            sample_valid <= 1'b0;

            if (enable && adc_response_valid &&
                (adc_response_channel == channel_select)) begin
                sample_valid   <= 1'b1;
                sample_data    <= adc_response_data;
                sample_channel <= adc_response_channel;
            end
        end
    end

endmodule
